HARNESS = 'use c6_core::{unit::Limits,player_ai_governors::*};\nfn mix(h:&mut u64,v:i64){for b in v.to_le_bytes(){*h=(*h^u64::from(b)).wrapping_mul(1099511628211)}}\n#[allow(non_snake_case)] fn p_CityId(v:&CityId,h:&mut u64){mix(h,v.owner as i64);mix(h,v.component_type as i64);mix(h,v.id as i64);}\n#[allow(non_snake_case)] fn p_GovernorAnalysis(v:&GovernorAnalysis,h:&mut u64){mix(h,v.player_id as i64);mix(h,v.governor_hash as i64);mix(h,v.city_ids.len() as i64);for v in &v.city_ids{p_CityId(&v,h);}mix(h,v.values_q8.len() as i64);for v in &v.values_q8{mix(h,*v as i64);}}\n#[allow(non_snake_case)] fn p_GovernorPromotionAnalysis(v:&GovernorPromotionAnalysis,h:&mut u64){mix(h,v.player_id as i64);mix(h,v.promotion_hash as i64);mix(h,v.for_governor_hashes.len() as i64);for v in &v.for_governor_hashes{mix(h,*v as i64);}mix(h,v.value_q8 as i64);}\n#[allow(non_snake_case)] fn p_Governors(v:&Governors,h:&mut u64){mix(h,v.player_id as i64);mix(h,v.done_off_turn as i64);mix(h,v.governor_analyses.len() as i64);for v in &v.governor_analyses{mix(h,v.hash as i64);p_GovernorAnalysis(&v.value,h);}mix(h,v.promotion_analyses.len() as i64);for v in &v.promotion_analyses{mix(h,v.hash as i64);p_GovernorPromotionAnalysis(&v.value,h);}}\nfn main() {\n let args:Vec<_>=std::env::args().collect();let all=std::fs::read(&args[1]).unwrap();let mut at=0;let mut records=0;let mut digest=14695981039346656037u64;\n while at<all.len() { let n=u32::from_le_bytes(all[at..at+4].try_into().unwrap()) as usize;at+=4;let raw=&all[at..at+n];at+=n;\n let (v,used,items)=Governors::decode_prefix_with_items(raw,Limits{max_bytes:n,max_items:n}).unwrap();assert_eq!(used,n);\n p_Governors(&v,&mut digest);let exact=Limits{max_bytes:n,max_items:items};assert_eq!(Governors::decode(raw,exact).unwrap(),v);assert_eq!(v.encode_with_items(exact).unwrap(),(raw.to_vec(),items));\n let cuts=u32::from_le_bytes(all[at..at+4].try_into().unwrap()) as usize;at+=4;for _ in 0..cuts{let end=u32::from_le_bytes(all[at..at+4].try_into().unwrap()) as usize;at+=4;assert!(end<n);assert!(Governors::decode(&raw[..end],exact).is_err());}\n let short=Limits{max_bytes:n-1,..exact};assert_eq!(Governors::decode(raw,short),Err(Error::ResourceLimit));assert_eq!(v.encode(short),Err(Error::ResourceLimit));\n if items>0 {let short=Limits{max_items:items-1,..exact};assert_eq!(Governors::decode(raw,short),Err(Error::ResourceLimit));assert_eq!(v.encode(short),Err(Error::ResourceLimit));}\n let mut tail=raw.to_vec();tail.extend_from_slice(&[91;128]);assert_eq!(Governors::decode(&tail,exact),Err(Error::Trailing));assert_eq!(Governors::decode_prefix_with_items(&tail,exact).unwrap(),(v,n,items));records+=1;\n } assert_eq!(records,86);println!("{records} {digest}");\n}'

def projection(raw):
    pos=0;items=0;values=[];rebuilt=bytearray();counts={};cuts=set()
    def scalar(t,emit=True,tracked=True):
        nonlocal pos
        fmt={'i':'<i','u':'<I','b':'<B','s':'<h'}[t];n=struct.calcsize(fmt)
        if tracked:cuts.update([pos,pos+1] if n>1 else [pos])
        v=struct.unpack_from(fmt,raw,pos)[0];pos+=n
        if tracked:cuts.add(pos)
        rebuilt.extend(struct.pack(fmt,v))
        if emit:values.append(v)
        return v
    def read(t,tracked=True):
        nonlocal items
        if t in ('i','u','b','s'):return scalar(t,tracked=tracked)
        if t.startswith('['):
            n=scalar('u',tracked=tracked);items+=n
            result=[read(t[1:-1],tracked) for j in range(n)]
            if tracked:cuts.add(pos)
            return result
        if t.startswith('{'):return dict(hash=scalar('u',tracked=tracked),value=read(t[1:-1],tracked))
        version,fields=SCHEMAS[t]
        counts[t]=counts.get(t,0)+1
        if version is not None and scalar('u',False,tracked)!=version:raise ValueError('version '+t)
        return {name:read(kind,tracked) for name,kind in fields}
    value=read('Governors')
    if pos!=len(raw) or rebuilt!=raw:raise ValueError('typed extent/repacking')
    return value,items,values,counts,sorted(n for n in cuts if n<len(raw))

def candidate(pin,records,expected_digest):
    pin=subprocess.check_output(['git','rev-parse',pin+'^{commit}'],cwd=ROOT,text=True).strip()
    archive=subprocess.check_output(['git','archive',pin],cwd=ROOT)
    with tempfile.TemporaryDirectory(prefix='c6-ai-governors-') as tmp:
        tmp=Path(tmp);source=tmp/'source';source.mkdir()
        subprocess.run(['tar','-x','-C',str(source)],input=archive,check=True)
        if (source/'tools/linux/player_ai_governors_audit.py').read_bytes()!=Path(__file__).read_bytes():raise ValueError('driver not committed at pin')
        # Gate every archived regular source against its immutable Git content,
        # before and after all builds. Build artifacts are outside this set.
        paths=subprocess.check_output(['git','ls-tree','-r','--name-only',pin],cwd=ROOT,text=True).splitlines()
        identities={}
        for path in paths:
            p=source/path
            if p.is_symlink():continue
            expected=subprocess.check_output(['git','show',pin+':'+path],cwd=ROOT)
            if p.read_bytes()!=expected:raise ValueError('archive source mismatch '+path)
            identities[path]=sha(expected)
        subprocess.run(['cargo','test','--offline','-p','c6-core','player_ai_governors'],cwd=source,check=True)
        subprocess.run(['cargo','clippy','--offline','-p','c6-core','--all-targets','--','-D','warnings'],cwd=source,check=True)
        subprocess.run(['cargo','build','--offline','--release','-p','c6-core'],cwd=source,check=True)
        (tmp/'main.rs').write_text(HARNESS)
        subprocess.run(['rustc','--edition=2021','-Dwarnings','-O',str(tmp/'main.rs'),'--extern','c6_core='+str(source/'target/release/libc6_core.rlib'),'-L','dependency='+str(source/'target/release/deps'),'-o',str(tmp/'candidate')],check=True)
        (tmp/'records').write_bytes(records)
        count,digest=map(int,subprocess.check_output([str(tmp/'candidate'),str(tmp/'records')],text=True).split())
        if count!=86 or digest!=expected_digest:raise ValueError('independent typed projection mismatch')
        for path,digest_source in identities.items():
            if sha((source/path).read_bytes())!=digest_source:raise ValueError('source changed during build '+path)
        return dict(source_commit=pin,archive_sha256=sha(archive),sources=identities,harness_sha256=sha(HARNESS.encode()),candidate_sha256=sha((tmp/'candidate').read_bytes()),records=count,typed_projection_digest=digest,all_archived_sources_checked_before_and_after=True,exported_archive_unchanged=True,cargo_tests=True,clippy_strict_all_targets=True,native_truncation_cuts="all count fields and containers; all scalar boundaries plus first interior byte in every repeated row",source_carrier_every_truncation=True,exact_byte_item_caps=True,one_short_byte_item_caps=True,strict_trailing=True,prefix_tail=True)

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);p.add_argument('--source-commit');p.add_argument('--assets',type=Path,default=ROOT.parent/'c6-assets-linux');p.add_argument('--private-root',type=Path,default=ROOT.parent/'c6-ghidra');a=p.parse_args()
