    report=dict(schema='c6-linux-player-ai-governors-v1',checks_passed=True,gamecore_sha256=GAME_SHA,methods=METHODS,dwarf_sha256=DWARF_SHA,wire_schemas=SCHEMAS,audit_source_sha256=sha(Path(__file__).read_bytes()),fixtures=reports,typed_projection_digest=digest,complete_current_saved_wire=True,legacy_versions=False,definition_remapping=False,native_read_effects=False,original_execution=False,private_writes=False,planning_only_exclusion_proven=False,gameplay_rng_in_scope=True,full_player=False,world_import=False,actions=False,turns=False,next_player_component='AI::GrandStrategic',unknown_save_bytes_masked=False,recorded_raw_save_load_difference_bytes=89198,attribution_reference_revision='5af389445118bed2bdebf7a8a42b219c8fba5175',validation_cuts='Actual Governors and nested analysis hooks validate complete production grammar')
    if a.source_commit:report['candidate']=candidate(a.source_commit,corpus,digest)
    a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(dict(checks_passed=True,records=86)))
